{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Fees — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#fbfbfb; --muted:#6b6b6b; --accent:#6c5ce7; --card:#ffffff; --glass: rgba(255,255,255,0.6);
      --shadow: 0 6px 24px rgba(15,15,20,0.06);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
    }
    html,body{height:100%;margin:0;background:var(--bg);color:#111}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background-image:url('assets/img/pattern.svg');background-size:320px;border-bottom:1px solid #eee}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#00c2a8);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:18px;color:#333;text-decoration:none;font-weight:600}
    main{max-width:980px;margin:36px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:start;margin-bottom:28px}
    .panel{background:var(--card);padding:22px;border-radius:12px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px;font-size:22px}
    p.lead{margin:0;color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px;margin-top:18px}
    .card{padding:18px;border-radius:10px;background:linear-gradient(180deg,#fff, #fbfbff);box-shadow:var(--shadow);border:1px solid rgba(9,9,11,0.03)}
    .price{font-weight:700;color:var(--accent);font-size:20px;margin:10px 0}
    .muted{color:var(--muted);font-size:14px}
    .cta{display:inline-block;padding:10px 14px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none;margin-top:12px}
    footer{padding:26px;text-align:center;color:var(--muted);font-size:13px}

    /* reveal */
    .revealable{opacity:0;transform:translateY(18px) scale(0.995);transition:opacity .6s ease,transform .6s cubic-bezier(.2,.9,.2,1)}
    .revealable.revealed{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){
      .revealable{transition:none;transform:none;opacity:1}
    }

    /* small helper */
    .note{font-size:13px;color:var(--muted);margin-top:12px}
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#f5f6ff;color:#2b2b2b;font-weight:600}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Practice</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="panel revealable" data-reveal>
        <h1>Investment & Engagement Options</h1>
        <p class="lead">Therapy can look different depending on timing, needs, and life rhythm. The options below are framed to help you choose how steady or concentrated you want support to be.</p>
        <p class="note">All work is confidential. Sessions respect clinical boundaries and are not emergency services. See notes below.</p>
      </div>

      <aside class="panel revealable" data-reveal>
        <div style="font-size:13px;color:var(--muted)">Quick contact</div>
        <div style="margin-top:12px;font-weight:700">{{PHONE}}</div>
        <div style="margin-top:6px;color:var(--muted)">{{EMAIL}}</div>
        <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
      </aside>
    </section>

    <section class="revealable" data-reveal>
      <div class="grid">
        <div class="card">
          <div class="pill">Guided Cohort</div>
          <h3 style="margin-top:10px">6-Week Focus Series</h3>
          <div class="price">$480 per participant</div>
          <div class="muted">Small cohort learning + weekly 75-minute facilitated sessions. Practical tools, shared reflection, and short individual check-ins as needed.</div>
          <div style="margin-top:12px"><a class="cta" href="book.html">Reserve a spot</a></div>
        </div>

        <div class="card">
          <div class="pill">Focused Series</div>
          <h3 style="margin-top:10px">4-Session Planning Package</h3>
          <div class="price">$320</div>
          <div class="muted">A compact, goal-oriented sequence to clarify priorities and build manageable habits. Ideal for defined concerns or transitions.</div>
          <div style="margin-top:12px"><a class="cta" href="book.html">Start your plan</a></div>
        </div>

        <div class="card">
          <div class="pill">Drop-in Support</div>
          <h3 style="margin-top:10px">Single Session</h3>
          <div class="price">$120</div>
          <div class="muted">One-off sessions for immediate perspective, safety planning, or short-term problem-solving. Helpful if you need a single conversation.</div>
          <div style="margin-top:12px"><a class="cta" href="book.html">Book a session</a></div>
        </div>
      </div>

      <div style="margin-top:18px" class="panel">
        <h4 style="margin:0 0 8px">Payment & insurance</h4>
        <p class="muted">I accept private pay. Some clients submit receipts to their insurer; please check your plan for out-of-network mental health benefits. Sliding scale spots may be available in limited circumstances; reach out directly to discuss.</p>
        <p class="note">Fees subject to change; your booked session confirms the rate communicated at booking.</p>
      </div>
    </section>

    <section class="panel revealable" data-reveal style="margin-top:20px">
      <h4 style="margin:0 0 8px">Clinical boundaries, confidentiality, and crisis</h4>
      <p class="muted">Sessions are private and protected under clinical confidentiality. Limits to confidentiality include imminent risk of harm, mandated reporting laws, or court order. This practice does not provide emergency services. If you are in immediate danger or need urgent help, please call local emergency services or a crisis line in {{CITY}}, {{STATE}}.</p>
    </section>
  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — Compassionate clinical work in {{CITY}}, {{STATE}} • <a href="contact.html">Connect</a></div>
  </footer>

  <script>
    (function(){
      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      var items = document.querySelectorAll('[data-reveal]');
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(e){
          if (e.isIntersecting) { e.target.classList.add('revealed'); io.unobserve(e.target);} 
        });
      },{threshold:0.12});
      items.forEach(function(el){ el.classList.add('revealable'); io.observe(el); });
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#666;--accent:#ff6b6b;--card:#ffffff;--shadow:0 8px 30px rgba(12,12,20,0.06)}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#111}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;border-bottom:1px solid #f2f2f2}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#ff9a9e,var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:14px;text-decoration:none;color:#222;font-weight:600}
    main{max-width:980px;margin:28px auto;padding:0 20px}
    h1{font-size:22px}
    .faq-list{margin-top:18px}
    .faq{background:#fff;border-radius:10px;padding:16px;margin-bottom:10px;box-shadow:var(--shadow);border:1px solid rgba(0,0,0,0.03)}
    .q{font-weight:700}
    .a{color:var(--muted);margin-top:8px}
    .muted{color:var(--muted)}
    .planner{margin-top:22px;padding:16px;border-radius:12px;background:linear-gradient(180deg,#fff,#fffbfb);box-shadow:var(--shadow)}
    label{display:block;margin-top:10px;font-size:13px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6e6e6;margin-top:6px}
    button.primary{background:var(--accent);color:#fff;border:0;padding:10px 12px;border-radius:8px;margin-top:10px}
    pre.summary{white-space:pre-wrap;background:#fafafa;border-radius:8px;padding:12px;margin-top:10px;border:1px solid #f0f0f0}

    /* reveal */
    .revealable{opacity:0;transform:translateY(18px);transition:opacity .5s ease,transform .5s ease}
    .revealable.revealed{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){ .revealable{transition:none;opacity:1;transform:none} }
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Practice</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="revealable" data-reveal>
      <h1>Frequently asked questions</h1>
      <p class="muted">Below are brief answers to common questions. If you don’t see what you need, reach out via <a href="contact.html">contact</a> or book a brief consult.</p>
    </section>

    <section class="faq-list">
      <div class="faq revealable" data-reveal>
        <div class="q">What approaches do you use?</div>
        <div class="a">I draw from evidence-informed therapies chosen to fit your goals—practical strategies, reflective inquiry, and skills training. We collaborate on a plan tailored to your life and values.</div>
      </div>

      <div class="faq revealable" data-reveal>
        <div class="q">How long will I work with you?</div>
        <div class="a">That depends on your goals. Some people find a 4-session plan clarifying; others join a 6-week cohort or continue with weekly sessions. We set expectations together and revisit them periodically.</div>
      </div>

      <div class="faq revealable" data-reveal>
        <div class="q">Do you accept insurance?</div>
        <div class="a">This practice uses private pay. I can provide a receipt you may submit to your insurer for possible reimbursement. Please check your specific plan before booking.</div>
      </div>

      <div class="faq revealable" data-reveal>
        <div class="q">What if I am in crisis?</div>
        <div class="a">I do not provide emergency care. If you are at immediate risk, please call local emergency services or a crisis line in {{CITY}}, {{STATE}}.</div>
      </div>
    </section>

    <section class="planner revealable" data-reveal>
      <h2 style="margin:0">Session Planner</h2>
      <p class="muted">Build a simple plan to guide your next sessions. Use the copy button to save or share a plaintext summary.</p>

      <label for="concern">Primary concern or focus</label>
      <input id="concern" placeholder="e.g., sleep disruption, career pivot, parenting boundaries" />

      <label for="frequency">Preferred rhythm</label>
      <select id="frequency">
        <option value="Weekly">Weekly</option>
        <option value="Biweekly">Biweekly</option>
        <option value="6-week cohort">6-week cohort</option>
        <option value="Single session">Single session</option>
      </select>

      <label for="goals">Top goals (comma-separated)</label>
      <input id="goals" placeholder="e.g., reduce anxiety, clearer decisions, better sleep" />

      <label for="notes">Anything to tell your clinician before the first session?</label>
      <textarea id="notes" rows="3" placeholder="Brief context, access needs, or what has helped before"></textarea>

      <button class="primary" id="build">Build plan</button>
      <button style="margin-left:8px" id="copy">Copy summary</button>

      <pre class="summary" id="summary" aria-live="polite">No plan built yet.</pre>
    </section>

    <section class="revealable" data-reveal style="margin-top:18px;padding:12px;border-radius:10px;background:#fff;border:1px solid #f2f2f2">
      <h4 style="margin:0 0 6px">Clinical note</h4>
      <p class="muted">Therapeutic work is collaborative and confidential within professional limits. This page is informational and not a substitute for one-to-one care. If you have immediate safety concerns, contact emergency services.</p>
    </section>
  </main>

  <script>
    // Scroll reveal with reduced-motion respect
    (function(){
      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      var els = document.querySelectorAll('[data-reveal]');
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if (e.isIntersecting) { e.target.classList.add('revealed'); obs.unobserve(e.target); } });
      },{threshold:0.1});
      els.forEach(function(el){ obs.observe(el); });
    })();

    // Session Planner widget
    (function(){
      var build = document.getElementById('build');
      var copy = document.getElementById('copy');
      var summary = document.getElementById('summary');
      function makeSummary(){
        var concern = document.getElementById('concern').value.trim();
        var freq = document.getElementById('frequency').value;
        var goals = document.getElementById('goals').value.trim();
        var notes = document.getElementById('notes').value.trim();
        if(!concern){ summary.textContent = 'Please add a primary concern to build a plan.'; return; }
        var lines = [];
        lines.push('Session Planner — {{BUSINESS_NAME}}');
        lines.push('Primary focus: ' + concern);
        lines.push('Proposed rhythm: ' + freq);
        if(goals) lines.push('Goals: ' + goals);
        if(notes) lines.push('Context / access notes: ' + notes);
        lines.push('Suggested approach: Collaborative goal-setting, skill-building, and check-ins. No guarantees—progress varies by person.');
        lines.push('Contact to book: ' + '{{PRIMARY_CTA_LABEL}}' + ' — ' + '{{PRIMARY_CTA_URL}}');
        summary.textContent = lines.join('\n');
      }
      build.addEventListener('click', makeSummary);
      copy.addEventListener('click', function(){
        var text = summary.textContent;
        if(!text || text === 'No plan built yet.' || text.indexOf('Please add')===0) return alert('Please build a plan first.');
        if(navigator.clipboard && navigator.clipboard.writeText){
          navigator.clipboard.writeText(text).then(function(){ alert('Plan copied to clipboard'); }, function(){ fallbackCopy(text); });
        } else { fallbackCopy(text); }
      });
      function fallbackCopy(t){
        var ta = document.createElement('textarea'); ta.value = t; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); alert('Plan copied to clipboard'); } catch(e){ alert('Could not copy automatically. Please select and copy manually.'); } document.body.removeChild(ta);
      }
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfcff;--muted:#6b7280;--accent:#00a3ff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#111}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;background-image:url('assets/img/pattern.svg');background-size:360px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#00c2ff,#0077ff);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:12px;color:#111;text-decoration:none;font-weight:600}
    main{max-width:980px;margin:28px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(12,12,20,0.06)}
    label{display:block;font-size:13px;margin-top:12px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e9eef8;margin-top:6px}
    button.cta{background:var(--accent);color:#fff;border:0;padding:10px 14px;border-radius:10px;margin-top:12px}
    .muted{color:var(--muted)}
    .small{font-size:13px;color:var(--muted)}
    pre.summary{white-space:pre-wrap;background:#f7fbff;padding:12px;border-radius:8px;border:1px solid #eaf4ff;margin-top:10px}

    /* reveal */
    .revealable{opacity:0;transform:translateY(12px);transition:opacity .6s ease,transform .6s ease}
    .revealable.revealed{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){ .revealable{transition:none;opacity:1;transform:none} }
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">T</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Practice</a>
      <a href="fees.html">Fees</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div class="card revealable" data-reveal>
        <h1 style="margin:0 0 6px">Plan a visit</h1>
        <p class="small">Choose a format that fits your current need. If you’re unsure, the planner to the right can help you prepare a short summary for the first meeting.</p>

        <form id="bookingForm" style="margin-top:12px">
          <label for="name">Your full name</label>
          <input id="name" required />

          <label for="email">Email</label>
          <input id="email" type="email" required />

          <label for="type">Session type</label>
          <select id="type">
            <option value="Single session">Single session</option>
            <option value="4-session package">4-session package</option>
            <option value="6-week cohort">6-week cohort</option>
          </select>

          <label for="when">Preferred days / times</label>
          <input id="when" placeholder="e.g., Tue afternoons, Fri morning" />

          <label for="message">Anything you'd like the clinician to know in advance?</label>
          <textarea id="message" rows="4" placeholder="Short context, access needs, or what has helped before"></textarea>

          <div style="display:flex;gap:8px;align-items:center">
            <button class="cta" type="button" id="submitBtn">Request booking</button>
            <div class="small muted">We’ll reply to {{EMAIL}} with next steps.</div>
          </div>
        </form>

        <div style="margin-top:12px;color:var(--muted);font-size:13px">Confidentiality note: Clinical confidentiality applies. Limits include imminent risk of harm and mandated reporting. This practice does not provide emergency services.</div>
      </div>

      <aside class="card revealable" data-reveal>
        <h3 style="margin:0">Session Planner</h3>
        <p class="small">Build a short summary to paste into the booking form or to copy and bring to your first session.</p>

        <label for="p_concern">Primary concern</label>
        <input id="p_concern" placeholder="e.g., difficulty concentrating, grief, relationship strain" />

        <label for="p_freq">Preferred rhythm</label>
        <select id="p_freq">
          <option>Weekly</option>
          <option>Biweekly</option>
          <option>6-week cohort</option>
          <option>Single session</option>
        </select>

        <label for="p_goals">Top goals</label>
        <input id="p_goals" placeholder="e.g., better sleep, clearer boundaries" />

        <label for="p_notes">Quick context</label>
        <textarea id="p_notes" rows="3" placeholder="Concise context or access needs"></textarea>

        <button class="cta" id="p_build">Create summary</button>
        <button id="p_copy" style="margin-left:8px;padding:10px;border-radius:8px">Copy</button>

        <pre class="summary" id="p_summary">No summary yet.</pre>
      </aside>
    </div>
  </main>

  <script>
    // reveal
    (function(){
      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      var els = document.querySelectorAll('[data-reveal]');
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('revealed'); obs.unobserve(e.target);} });
      },{threshold:0.12});
      els.forEach(function(el){ obs.observe(el); });
    })();

    // Booking form: simple local handler (no server)
    (function(){
      var btn = document.getElementById('submitBtn');
      btn.addEventListener('click', function(){
        var name = document.getElementById('name').value.trim();
        var email = document.getElementById('email').value.trim();
        if(!name || !email){ alert('Please provide your name and email to request a booking.'); return; }
        // In a real site, form submission would be sent to a server or scheduling system.
        alert('Thanks, ' + name + '. A booking request has been noted. We will follow up at ' + email + '.');
      });
    })();

    // Planner widget logic
    (function(){
      var build = document.getElementById('p_build');
      var copy = document.getElementById('p_copy');
      var summary = document.getElementById('p_summary');
      function buildSummary(){
        var concern = document.getElementById('p_concern').value.trim();
        var freq = document.getElementById('p_freq').value;
        var goals = document.getElementById('p_goals').value.trim();
        var notes = document.getElementById('p_notes').value.trim();
        if(!concern){ summary.textContent = 'Please enter a primary concern.'; return; }
        var out = [];
        out.push('Session Summary — ' + '{{BUSINESS_NAME}}');
        out.push('Focus: ' + concern);
        out.push('Preferred rhythm: ' + freq);
        if(goals) out.push('Goals: ' + goals);
        if(notes) out.push('Notes: ' + notes);
        out.push('Booking contact: ' + '{{EMAIL}}');
        summary.textContent = out.join('\n');
      }
      function copyText(){
        var t = summary.textContent;
        if(!t || t.indexOf('Please enter')===0 || t==='No summary yet.') return alert('Please create a summary first.');
        if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(function(){ alert('Summary copied'); }, function(){ fallback(t); }); }
        else fallback(t);
      }
      function fallback(t){ var ta=document.createElement('textarea'); ta.value=t; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); alert('Summary copied'); }catch(e){ alert('Copy failed.'); } document.body.removeChild(ta); }
      build.addEventListener('click', buildSummary);
      copy.addEventListener('click', copyText);
    })();
  </script>
</body>
</html>"} 
